package io.lumine.mythic.lib.api.crafting.ingredients; import io.lumine.mythic.lib.api.crafting.uimanager.ProvidedUIFilter; import java.util.*; public class MythicRecipeIngredient { private final MythicIngredient ingredient; public MythicRecipeIngredient(MythicIngredient i){ingredient=Objects.requireNonNull(i);} public MythicRecipeIngredient(ProvidedUIFilter f){if(f==null)throw new IllegalArgumentException("filter");ingredient=new MythicIngredient(f.toString(),f);} public MythicIngredient getIngredient(){return ingredient;} }
